export const HELP_TEXT = `${USAGE_LINE}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n`;

export class CliExit extends Error {
  constructor(code, { stdout = '', stderr = '' } = {}) {
    super(`cli exit ${code}`);
    this.name = 'CliExit';
    this.code = code;
    this.stdout = stdout;
    this.stderr = stderr;
  }
}

function createUsageError(message) {
  return new CliExit(2, {
    stderr: `${USAGE_LINE}\n${PROGRAM_NAME}: error: ${message}\n`,
  });
}

function looksLikeOptionBoundary(token) {
  return token !== undefined
    && token !== '-'
    && token.startsWith('-')
    && !isPythonIntLiteral(token);
}

function readIntOption(optionName, argv, index) {
  const token = argv[index];
  let rawValue;
  let nextIndex = index;

  if (token === optionName) {
    const candidate = argv[index + 1];

    if (candidate === undefined || candidate === '--' || looksLikeOptionBoundary(candidate)) {
      throw createUsageError(`argument ${optionName}: expected one argument`);
    }

    rawValue = candidate;
    nextIndex = index + 1;
  } else {
    rawValue = token.slice(optionName.length + 1);
  }

  try {
    return { nextIndex, value: parsePythonIntLiteral(rawValue) };
  } catch {
    throw createUsageError(`argument ${optionName}: invalid int value: '${rawValue}'`);
  }
}

function collectMissing(values) {
  const missing = [];

  if (values.a === undefined) {
    missing.push('--a');
  }

  if (values.b === undefined) {
    missing.push('--b');
  }

  return missing;
}

export function parseCommandLine(argv) {
  const values = { a: undefined, b: undefined };
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      throw new CliExit(0, { stdout: HELP_TEXT });
    }

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (token === '--a' || token.startsWith('--a=')) {
      const parsed = readIntOption('--a', argv, index);
      values.a = parsed.value;
      index = parsed.nextIndex;
      continue;
    }

    if (token === '--b' || token.startsWith('--b=')) {
      const parsed = readIntOption('--b', argv, index);
      values.b = parsed.value;
      index = parsed.nextIndex;
      continue;
    }

    extras.push(token);
  }

