  if (missing.length > 0) {
    throw createUsageError(`the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    throw createUsageError(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return values;
